{"code": "import os

def find_largest_file(start_path):
    largest_file = None
    max_size = -1

    for root, dirs, files in os.walk(start_path):
        for name in files:
            filepath = os.path.join(root, name)
            try:
                size = os.path.getsize(filepath)
                if size > max_size:
                    max_size = size
                    largest_file = filepath
            except OSError:
                continue
    return largest_file

largest = find_largest_file('/workspace/project/')
if largest:
    relative_path = os.path.relpath(largest, '/workspace')
    print(relative_path)
else:
    print("No files found.")
